def process_input_string(S: str) -> None:
    n = len(S)
    a_end = 0
    while a_end < n and S[a_end] == 'A':
        a_end += 1

    b_end = a_end
    while b_end < n and S[b_end] == 'B':
        b_end += 1

    c_end = b_end
    while c_end < n and S[c_end] == 'C':
        c_end += 1

    if c_end == n:
        print('Yes')
    else:
        print('No')
